maliceCost.text:
const _MALICE_COST_MUL=0.5; // 악의 소비 50% 할인
function _malCost(v){
  const _n=Number(v)||0;
  if(_n<=0)return 0;
  return Math.max(1,Math.ceil(_n*_MALICE_COST_MUL));
}

slotCalculations.text:
function _skById(id){return _SK_MAP.get(id)||null}

// 선택 슬롯 계약: 일반은 1~4, 분노 폭발(지옥강타 계열)은 Space, 영역은 F에만 1개 장착한다.
function _isAreaSkillId(id){const sk=_skById(id);return !!(sk&&sk.cat==='tech'&&sk.act&&!sk.fixed)}
function _isRageBurstSkillId(id){const sk=_skById(id);return id==='giantSlam'||id==='giantSlam2'||!!(sk&&sk.cat==='rage')}
function _canAssignSkillSlot(id,slotIdx){
  const sk=_skById(id);
  if(!sk||!sk.act||sk.ult||sk.fixed)return false;
  if(_isAreaSkillId(id))return slotIdx===5;
  if(_isRageBurstSkillId(id))return slotIdx===4;
  return slotIdx>=0&&slotIdx<4;
}
function _findAutoSkillSlot(id){
  if(SKILL_SLOTS.includes(id))return -1;
  if(_isAreaSkillId(id))return SKILL_SLOTS[5]===null&&_canAssignSkillSlot(id,5)?5:-1;
  if(_isRageBurstSkillId(id))return SKILL_SLOTS[4]===null&&_canAssignSkillSlot(id,4)?4:-1;
  for(let i=0;i<4;i++){if(SKILL_SLOTS[i]===null&&_canAssignSkillSlot(id,i))return i}
  return -1;
}

absorbed.text:
function _getAllAbsorbed(){
  const out=[];
  for(const fk of Object.keys(_FUSE_PAIRS)){
    if(!_isFused(fk))continue;
    const ab=_getAbsorbed(fk);
    for(let i=0;i<ab.length;i++){if(out.indexOf(ab[i])===-1)out.push(ab[i])}
  }
  return out;
}

