const _hasUltLearned=false; // 필살기 전부 습득 가능
const _lvMet=sk.reqLv?P.lv>=sk.reqLv:true;
const canLearn=!learned&&_reqMet&&_lvMet&&P.sp>=sk.spCost&&G.mats>=_malCost(sk.matCost||0);
const _skMaxLv=20;
const _skLvLock=Math.min(20,~~(P.lv/50)+1); // 50렙당 +1 (Lv1=1렙, Lv50=2렙, Lv100=3렙, ... Lv950=20렙)

