click.text:
function _skClick(){
    if(!learned){
      // 습득
      const _learnMat=_malCost(sk.matCost||0);
      if(P.sp<sk.spCost||G.mats<_learnMat){showPH(_T('자원 부족!'),'#ff4444');return}
      P.skills[sk.id]=1;P.sp-=sk.spCost;G.mats-=_learnMat;
      // chainAssault 습득 시 chainSlam 자동 부여
      if(sk.id==='chainAssault'&&!P.skills.chainSlam)P.skills.chainSlam=1;
      SFX.levelup();showPH(_T(sk.name)+_L(' 습득!',' Learned!'),'#ff4400');
      addTxt(P.x,P.y-30,_T(sk.name)+_L(' 습득!',' Learned!'),'#ff4400',80);
      // 돌진류 스킬 습득 시 자동 세팅
      if(SKILL_SLOT_DEFS.charge.skills.includes(sk.id)){P.activeChargeSk=sk.id;updateSkSlot()}
      if(SKILL_SLOT_DEFS.bow&&SKILL_SLOT_DEFS.bow.skills.includes(sk.id)){if(!P.activeBowSk||P.activeBowSk==='normal')P.activeBowSk=sk.id;if(typeof updateBowSlot==='function')updateBowSlot()}
      if(SKILL_SLOT_DEFS.tech&&SKILL_SLOT_DEFS.tech.skills.includes(sk.id)){P.activeTechSk=sk.id;if(typeof updateBowSlot==='function')updateBowSlot()}
      if(SKILL_SLOT_DEFS.magic&&SKILL_SLOT_DEFS.magic.skills.includes(sk.id)){if(!P.activeMagicSk||P.activeMagicSk==='fireball')P.activeMagicSk=sk.id;if(typeof updateMagicSlot==='function')updateMagicSlot()}
      if(SKILL_SLOT_DEFS.q&&SKILL_SLOT_DEFS.q.skills.includes(sk.id)&&sk.id!=='parry'){P.activeQSk=sk.id;updateQSlot()}
      // LMB 스킬 습득 시 자동 세팅 (기검참 외 새 스킬 배우면 자동 전환)
      if(SKILL_SLOT_DEFS.lmb&&SKILL_SLOT_DEFS.lmb.skills.includes(sk.id)&&sk.id!=='kiSlash'){P.activeLMBSk=sk.id;updateSkSlot()}
      // 합체 흡수 스킬 슬롯 자동 해제 (통합)
      const _fuseKick=_getAllAbsorbed();
      for(let _fi=0;_fi<6;_fi++){if(_fuseKick.includes(SKILL_SLOTS[_fi]))SKILL_SLOTS[_fi]=null}
      // 액티브 스킬 → 숫자 슬롯 자동 배정
      if(sk.ult){if(!ULT_SLOT){ULT_SLOT=sk.id;addTxt(P.x,P.y-50,_T('필살기 배정!'),'#ff4444',40);_updateUltSlot()}}
      else if(sk.act&&!_fuseKick.includes(sk.id)){
        const _emptyIdx=_findAutoSkillSlot(sk.id);
        if(_emptyIdx>=0&&!SKILL_SLOTS.includes(sk.id)){SKILL_SLOTS[_emptyIdx]=sk.id;const _asLbl=(_emptyIdx<4?_L('슬롯 ','Slot ')+(_emptyIdx+1):_emptyIdx===4?_L('Space 슬롯','Space Slot'):_L('F슬롯','F Slot'));addTxt(P.x,P.y-50,_asLbl+_L(' 배정!',' Assigned!'),'#ff8844',40);updateQS()}
      }
    } else if(_isStormBurst||_isStormBeam||_isDimBlast||_isDimRush||_isDimFuse||_isDimSlam||_isDimThunder||_isSlamStorm||_isSynth||_isElemFuse||_isSixFuse||_isBladeFuse||_isIceFuse||_isBoneStorm||_isElecRepent||_isShieldFuse||_isPlagueFuse||_isPlagueVenom||_isHolyIce||_isHolyFuse||_isHolyW1||_isHolyW2||_isHolyW3||_isHolyW4||_isPillarSlam||_isPillarSpike||_isInfernoSlam||_isSiegeGhost||_isDualScarecrow||_isThunderGhost||_isTimeStep){
      // ═══ 통합 합체 강화: 전 스킬 동시 +1, 비용 = 구성원 upSp/upMat 합산 ═══
      const _fuseKey=_isStormBurst?'stormBurst':_isStormBeam?'stormBeam':_isDimBlast?'dimBlast':_isDimRush?'dimRush':_isDimThunder?'dimThunder':_isDimSlam?'dimSlam':_isDimFuse?'dimBreach':_isSlamStorm?'slamStorm':_isSynth?'whirlDet':_isElemFuse?'elemFuse':_isSixFuse?'sixFuse':_isBladeFuse?'bladeFuse':_isBoneStorm?'boneStorm':_isElecRepent?'elecRepent':_isShieldFuse?'shieldFuse':_isPlagueVenom?'plagueVenom':_isPlagueFuse?'plagueFuse':_isPillarSlam?'pillarSlam':_isPillarSpike?'pillarSpike':_isInfernoSlam?'infernoSlam':_isSiegeGhost?'siegeGhost':_isDualScarecrow?'dualScarecrow':_isThunderGhost?'thunderGhost':_isTimeStep?'timeStep':_isHolyW4?'holyWeak4':_isHolyW3?'holyWeak3':_isHolyW2?'holyWeak2':_isHolyW1?'holyWeak1':_isHolyIce?'holyIce':_isHolyFuse?'holyFuse':'iceMortar';
      const _fuseIds=_fuseKey==='stormBeam'?['whirlwind','detonate','giantSlam','fanShot','omniBeam','elemMissile']:_fuseKey==='elemFuse'?['fanShot','omniBeam','elemMissile']:_fuseKey==='slamStorm'?['whirlwind','detonate','giantSlam']:(_FUSE_PAIRS[_fuseKey]||[]);
      const _fuseSks=_fuseIds.map(id=>_skById(id)).filter(Boolean);
      const _fuseLv=Math.min(..._fuseIds.map(id=>P.skills[id]||1));
      if(_fuseLv>=_skMaxLv)return;
      const _gemC=_fuseIds.length;const _totalSp=_fuseUpSpCost(_fuseLv,_gemC);
      if(P.sp>=_totalSp){
        _fuseIds.forEach(id=>{P.skills[id]=Math.max(P.skills[id]||1,_fuseLv+1)});
        P.sp-=_totalSp;
        const _fCol=_fGrp?_fGrp.color:'#55ccff';
        SFX.levelup();addTxt(P.x,P.y-30,_T('합체 Lv.')+(_fuseLv+1)+(_fuseLv+1>=_skMaxLv?' MAX!!':'!'),_fCol,60);
      }
    } else {
      // 강화
      if(slv>=_skMaxLv||slv>=_skLvLock){if(slv>=_skLvLock&&slv<_skMaxLv)showPH('Lv'+(_skLvLock*100)+_L(' 도달 시 해금!',' to unlock!'),'#ff8844');return;}
      {const _upSp=_skillUpSpCost(slv,false),_upMat=_malCost(sk.upMat||0);if(P.sp<_upSp||G.mats<_upMat){showPH(_T('자원 부족!'),'#ff4444');return}
      P.skills[sk.id]++;P.sp-=_upSp;G.mats-=_upMat;}
      SFX.levelup();const nlv=P.skills[sk.id];
      addTxt(P.x,P.y-30,_T(sk.name)+' Lv.'+nlv+(nlv>=_skMaxLv?' MAX!!':'!!'),'#ffaa00',60);
    }
    renderSkillPanel();updateSkSlot();updateQS();dbSaveForce();
};

