    _bMin2.textContent='-';
    _bMin2.title=_L('레벨다운 / 취소','Level down / cancel');
    _bMin2.onmouseenter=()=>{_bMin2.style.background='rgba(120,40,40,0.7)'};
    _bMin2.onmouseleave=()=>{_bMin2.style.background='rgba(80,30,30,0.45)'};
    _bMin2.onclick=(ev)=>{ev.stopPropagation();_skMinusClick()};
    _btnRow2.appendChild(_bMin2);
  }
  if(canLearn||canUp){
    const _bPlus2=document.createElement('div');
    _bPlus2.dataset.nodrag='1';
    _bPlus2.style.cssText='padding:3px 8px;min-width:28px;background:rgba(60,40,15,0.6);border:1px solid #aa8833;border-radius:4px;color:#ffcc66;font-size:.95rem;text-align:center;cursor:pointer;font-weight:700;line-height:1.1';
    _bPlus2.textContent='+';
    _bPlus2.title=canLearn?( _L('습득','Learn') ):( _L('레벨업','Level up') );
    _bPlus2.onmouseenter=()=>{_bPlus2.style.background='rgba(80,55,20,0.7)'};
    _bPlus2.onmouseleave=()=>{_bPlus2.style.background='rgba(60,40,15,0.6)'};
    _bPlus2.onclick=(ev)=>{ev.stopPropagation();_skClick()};
    _btnRow2.appendChild(_bPlus2);
  }
  if(_btnRow2.children.length>0)d.appendChild(_btnRow2);
}

